import{_ as s,l as i,o as e,c as n,v as t,p as d,x as o,d as l,i as p,S as A}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"I/O 与 DMA","description":"","frontmatter":{"title":"I/O 与 DMA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/io-dma.md","filePath":"cs/io-dma.md","lastUpdated":1789023840000}'),c={name:"cs/io-dma.md"};function m(h,a,D,M,_,E){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="i-o-与-dma" tabindex="-1">I/O 与 DMA <a class="header-anchor" href="#i-o-与-dma" aria-label="Permalink to &quot;I/O 与 DMA&quot;">​</a></h1><div class="epigraph"><p>DMA 让设备在 CPU 不逐字节介入的情况下把块搬进内存；完成时用中断汇报。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Patterson and Hennessy 对 DMA 的整理</footer></div><p><a href="/cs/bio-block">上一课</a>把 <code>readpage</code> 派到某文件系统。<a href="/cs/buffer-dirty">缓冲与脏页</a>需要帧里出现磁盘字节。<a href="/cs/interrupt-bottom-half">中断下半部</a>已假定「设备会完成」。缺口是搬动本身：CPU 端口 I/O 一次一字节太贵；<strong>DMA</strong> 让控制器成为总线主设备。本课不引入网卡帧格式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可编程 I/O（PIO）：CPU 循环读端口，写入内存，期间不能干别的，吞吐被 CPU 速度绑死。中断驱动 I/O 仍可能每字符一中断。块设备与网卡需要突发：CPU 只写描述符（地址、长度），设备把数据写入物理帧，然后 IRQ。缺口不是 VFS 操作表，而是这条数据通路，以及「设备看见的是物理地址」与<a href="/cs/paging-vm">分页</a>的接头（IOMMU 或页锁）。</p><p>本课不写 PCIe 事务层。</p><p><span class="marginnote">DMA 地址必须是设备可达的物理（或 IOVA）连续描述。页 Cache 中的帧要钉住，直到传输结束，否则置换会抽走正在 DMA 的页。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>驱动：把缓冲钉在内存，填 DMA 描述符，敲门铃寄存器。设备传输。IRQ → 上半部清状态 → 下半部解锁页、标记 Cache 最新、唤醒 <code>read</code>。CPU 全程不拷用户可见的那一大块（内核到用户仍可能 <code>copy_to_user</code>，mmap 则可免）。</p>',9)),(e(),d(A,null,{default:o(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DRV%5B%22%E9%A9%B1%E5%8A%A8%E5%A1%AB%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%20--%3E%20DEV%5B%22%E8%AE%BE%E5%A4%87%20DMA%22%5D%0A%20%20DEV%20--%3E%20IRQ%5B%22%E5%AE%8C%E6%88%90%E4%B8%AD%E6%96%AD%22%5D%0A%20%20IRQ%20--%3E%20BH%5B%22%E4%B8%8B%E5%8D%8A%E9%83%A8%3A%20%E8%A7%A3%E9%94%81%E3%80%81%E5%94%A4%E9%86%92%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DMA 把 I/O 从「占用 CPU 的循环」变成「占用总线与中断配额」。调度因此能在等待磁盘时跑别的线程——这是整门 OS 课从进程到文件的闭合：阻塞是因为 DMA 还没完。一致性：若 Cache 与 DMA 同时看见同一行，架构要嗅探或显式写回；教学承认有一致性协议，不把总线时序写完。</p><p>与网络课的接头：网卡同样 DMA 帧到内存；但两台机器之间还没有「帧」这个名字。那是下一课分层的起点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 RDMA 的全部动词，不把轮询驱动（DPDK）当默认。也不把 DMA 写成攻击面分析。内存映射寄存器（MMIO）仍是 CPU 访存，与 DMA 互补：控制走 MMIO，大块数据走 DMA。</p><p>分散—聚集 DMA 让缓冲不必物理连续，描述符链指向多个帧。IOMMU 给设备一张自己的虚地址，限制它能写的物理范围。</p><p>未对齐或非 DMA 可达的缓冲要先拷到 bounce buffer，这是隐藏的 CPU 拷贝。</p><p>后课默认：一台机器可以把设备字节搬进帧。两台机器如何共享对「一帧」的命名与责任划分，下一课分层与端到端。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PIO 绑 CPU；DMA 让设备写物理缓冲，中断收尾。</li><li>页必须钉住；完成走已有的下半部路径。</li><li>跨机器的帧与协议分层是网络课的第一缺口。</li><li>出处：Tanenbaum and Bos, <em>MOS</em>；Patterson and Hennessy, <em>COD</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',10))])}const P=s(c,[["render",m]]);export{f as __pageData,P as default};
